import { createExportWorkShiftsJob } from '~/client';
import type { CreateExportWorkShiftsJobResponse, WorkShiftExportRequest } from '~/client';

export const useExportWorkShiftsList = defineMutation(() => {
  const {
    mutateAsync: exportWorkShiftsList,
    asyncStatus,
    data,
  } = useMutation({
    mutation: (data: NonNullable<WorkShiftExportRequest>): Promise<CreateExportWorkShiftsJobResponse> =>
      createExportWorkShiftsJob({ composable: '$fetch', body: ref(data) }),
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    exportWorkShiftsList,
    isExportWorkShiftsList: computed(() => asyncStatus.value === 'loading'),
    data,
  };
});
