<template>
  <Dialog
    v-model:open="open"
    @update:open="
      (value) => {
        if (value) exportFormat = { name: 'CSV', value: 'csv' };
      }
    "
  >
    <DialogTrigger as-child>
      <Button :disabled="disabled" :prepend-icon="FileUpIcon" data-testid="workshifts-export">Export</Button>
    </DialogTrigger>
    <DialogContent>
      <DialogHeader>
        <DialogTitle>Export Work Shifts List</DialogTitle>
        <DialogDescription>
          You can export the list of work shifts in CSV or XLS format. The currently applied filters are included.
        </DialogDescription>
      </DialogHeader>
      <LabeledSelect v-model="exportFormat" :items="exportFormats" label="Format" />
      <DialogFooter>
        <DialogClose as-child>
          <Button variant="outline">Cancel</Button>
        </DialogClose>
        <Button :loading="isExportWorkShiftsList" data-testid="workshifts-export-submit" @click="exportWorkShifts"
          >Export</Button
        >
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { FileUpIcon } from 'lucide-vue-next';
import { exportFormats } from '~/constants/export';
import { useExportWorkShiftsList } from '~/mutations/workshifts/exportWorkShiftsList';
import type { GetWorkShiftListData } from '~/client';

interface Props {
  disabled?: boolean;
  params: GetWorkShiftListData['query'];
}

const props = defineProps<Props>();

const exportFormat = ref<SelectItem<'csv' | 'xls'>>({ name: 'CSV', value: 'csv' });
const open = ref<boolean>(false);

const { isExportWorkShiftsList, exportWorkShiftsList } = useExportWorkShiftsList();

async function exportWorkShifts() {
  const fileType = exportFormat.value?.value;
  if (!fileType) return;

  // Export covers everything matching the filters, so the list's pagination is dropped.
  const { page: _page, size: _size, ...filters } = props.params ?? {};

  const job = await exportWorkShiftsList({ ...filters, file_type: fileType });
  open.value = false;
  if (job?.id)
    await navigateTo({
      name: 'exports-id',
      params: { id: job.id },
    });
}
</script>
